            MD_CHECK_CC( ( metric->SetDeltaReportReadEquation( "2 64 qw@0x198 UMUL 128 qw@0x190 UMUL UADD 256 qw@0x188 UMUL UADD 512 qw@0x180 UMUL UADD UMUL" ) ) );
            MD_CHECK_CC( ( metric->SetSnapshotReportDeltaFunction( "DELTA 32" ) ) );
