            MD_CHECK_CC( ( metric->SetSnapshotReportReadEquation( "2 64 dw@0xcc UMUL 128 dw@0xc8 UMUL UADD 256 dw@0xc4 UMUL UADD 512 dw@0xc0 UMUL UADD UMUL" ) ) );
