            MD_CHECK_CC( ( metric->SetSnapshotReportReadEquation( "2 64 dw@0xdc UMUL 128 dw@0xd8 UMUL UADD 256 dw@0xd4 UMUL UADD 512 dw@0xd0 UMUL UADD UMUL" ) ) );
